STATUS_LABELS = {
    "defect": "Igazolt működési hiány",
    "partial": "Részleges",
    "missing": "Hiányzik a vizsgált termékfelületről",
    "unqualified": "Megvalósult alap, kvalifikáció hiányzik",
    "source_only": "Csak célplatformi forrás / unrun",
    "optional": "További univerzális termékscope",
}


def generate():
    backlog = []
    for line in TASK_ROWS.strip().splitlines():
        if not line.strip():
            continue
        fields = line.split("|")
        assert len(fields) == 9, (len(fields), line)
        identifier, priority, status, effort, title, current, change, acceptance, prerequisites = fields
        domain = identifier.split("-")[0]
        domain_title, phase, paths, refs = DOMAINS[domain]
        backlog.append(dict(id=identifier, domain=domain, domain_title=domain_title,
                            priority=priority, observed_status=status, observed_status_hu=STATUS_LABELS[status],
                            effort=effort, title=title, current_boundary=current, proposed_change=change,
                            acceptance=acceptance, prerequisites=[] if prerequisites == "-" else prerequisites.split(","),
                            phase="F0" if priority == "P0" else phase,
                            scope="universal" if status == "optional" else "latex-research-ide",
                            paths=paths, source_ids=refs, proposed_state="planned",
                            platform_contract="Közös Rust és külön natív adapter; Mac teszt nem Windows/Linux runtime-eredmény."))
    ids = {item["id"] for item in backlog}
    assert len(ids) == len(backlog)
    for item in backlog:
        assert all(dep in ids for dep in item["prerequisites"]), item
    visiting, visited = set(), set()
    by_id = {item["id"]: item for item in backlog}
    def visit(identifier):
        assert identifier not in visiting, f"Dependency cycle at {identifier}"
        if identifier in visited:
            return
        visiting.add(identifier)
        for dependency in by_id[identifier]["prerequisites"]:
            visit(dependency)
        visiting.remove(identifier)
        visited.add(identifier)
    for identifier in ids:
        visit(identifier)
    (OUT / "sources.json").write_text(json.dumps(sources, ensure_ascii=False, indent=2) + "\n")
    (OUT / "backlog.json").write_text(json.dumps(backlog, ensure_ascii=False, indent=2) + "\n")
    columns = ["id", "domain_title", "priority", "observed_status_hu", "effort", "phase", "scope", "title", "current_boundary", "proposed_change", "acceptance", "prerequisites", "paths", "source_ids", "proposed_state", "platform_contract"]
    with (OUT / "backlog.csv").open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=columns)
        writer.writeheader()
        for item in backlog:
            writer.writerow({column: "; ".join(item[column]) if isinstance(item[column], list) else item[column] for column in columns})
    counts = dict(total=len(backlog), domains=len(DOMAINS), sources=len(sources),
                  priority=dict(sorted(Counter(item["priority"] for item in backlog).items())),
                  observed_status=dict(Counter(item["observed_status"] for item in backlog)),
                  scope=dict(Counter(item["scope"] for item in backlog)),
                  phase=dict(sorted(Counter(item["phase"] for item in backlog).items())))
    (OUT / "counts.json").write_text(json.dumps(counts, ensure_ascii=False, indent=2) + "\n")
    comparisons = []
    for row in COMPARISON_ROWS.strip().splitlines():
        identifier, capability, jetbrains, vscode, mac, windows, linux, tasks, refs = row.split("|")
        assert all(task in ids for task in tasks.split(",")), identifier
        comparisons.append(dict(id=identifier, capability=capability, jetbrains=jetbrains, vscode=vscode,
                                latexide_mac=mac, latexide_windows=windows, latexide_linux=linux,
                                backlog_ids=tasks.split(","), source_ids=refs.split(",")))
    (OUT / "comparison.json").write_text(json.dumps(comparisons, ensure_ascii=False, indent=2) + "\n")
    with (OUT / "comparison.csv").open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(comparisons[0]))
        writer.writeheader()
        for item in comparisons:
            writer.writerow({key: "; ".join(value) if isinstance(value, list) else value for key, value in item.items()})
    lines = ["# LaTeX IDE — teljes implementációs hiány- és módosításjegyzék", "", "Dátum: 2026-10-31. A felmérés [főjelentése](../IDE_AUDIT_2026-10-31.md) magyarázza a bizonyítékokat és az architektúrát.", "", f"**{len(backlog)} fejlesztési tétel, {len(DOMAINS)} témakör, {len(sources)} elsődleges külső forrás.** Ez követelményszintű jegyzék; a teljes Marketplace minden verziójának minden parancsát nem tekinti végesen auditált halmaznak.", "", "Gépi feldolgozás: [CSV](backlog.csv), [JSON](backlog.json), [forrásjegyzék](sources.json), [ellenőrzött darabszámok](counts.json). Minden javaslat állapota **planned**; a jelenlegi állapot és a javaslat elkészültsége külön mező.", "", "Prioritás: **P0** = széles kiadás előtti megbízhatósági kapu; **P1** = napi LaTeX-munka; **P2** = erős IDE-paritás; **P3** = bővített munkafolyamat; **P4** = teljes univerzális termékscope. P0 nem sürgős éles incidens minősítése.", "", "Méret: **S** = egy szűk szerződés/adapter; **M** = több komponens; **L** = új alrendszer; **XL** = külön termékszintű szakterület. Ezek relatív, nem mért ráfordítások; nem napbecslések és nem összeadható ütemterv.", "", "Fázis: F0 alapmegerősítés; F1 dokumentum/workspace; F2 nyelv/navigáció; F3 build/PDF; F4 kutatás/Git; F5 asszisztens/bővítés/devtools; F6 célplatform és kiadás; F7 univerzális szakterületek. A függőségi lista előfeltétel, a fázisszám tervezési csoport, nem szigorú topologikus sorrend.", "", "A kódhelyek a jelenlegi belépési pontok. A hiányzó alrendszert ezek mellé, közös Rust szolgáltatásként és külön natív adapterrel kell létrehozni; a könyvtár létezése nem jelenti a felsorolt hiányzó funkció megvalósulását.", ""]
    source_map = {source["id"]: source for source in sources}
    for domain, (title, _, paths, refs) in DOMAINS.items():
        items = [item for item in backlog if item["domain"] == domain]
        lines += [f"## {domain} — {title} ({len(items)} tétel)", "", "Jelenlegi belépési pontok: " + ", ".join(f"[{path}](../../{path})" for path in paths) + ".", "", "Összehasonlítási források: " + ", ".join(f"[{ref}: {source_map[ref]['title']}]({source_map[ref]['url']})" for ref in refs) + ".", "", "| Azonosító / P / méret / fázis | Jelenlegi képesség és határ | Implementálandó módosítás | Elfogadási feltétel | Függőség |", "| --- | --- | --- | --- | --- |"]
        for item in items:
            lines.append(f"| <a id=\"{item['id'].lower()}\"></a>**{item['id']}** · {item['priority']} · {item['effort']} · {item['phase']}<br>{item['title']} | **{item['observed_status_hu']}**. {item['current_boundary']} | {item['proposed_change']} | {item['acceptance']} | {', '.join(item['prerequisites']) or '—'} |")
        lines.append("")
    lines += ["## Részletes funkció-összehasonlítás", "", "50 képességcsalád, külön Mac/Windows/Linux állapottal. A JetBrains oszlopban a releváns termék vagy plugin szerepel: nem állítjuk, hogy minden IDE minden funkciót azonos kiadásban tartalmaz. A LaTeX-összevetés TeXiFy-IDEA és LaTeX Workshop bővítményeket is használ. A VS Code nyelvi/debug/test/remote funkcióinak egy része extension, nem az editor önálló alapfunkciója. A Code With Me dokumentált verziókompatibilitása és a LaTeX Workshop külső SyncTeX korlátja miatt teljes, feltétel nélküli versenytársparitást sem feltételezünk.", "", "Gépi változat: [comparison.csv](comparison.csv), [comparison.json](comparison.json).", "", "| ID / képesség | JetBrains referencia | VS Code referencia | LaTeX IDE Mac | Windows / Linux | Tétel / forrás |", "| --- | --- | --- | --- | --- | --- |"]
    for item in comparisons:
        citations = ", ".join(f"[{ref}]({source_map[ref]['url']})" for ref in item["source_ids"])
        lines.append(f"| **{item['id']}** {item['capability']} | {item['jetbrains']} | {item['vscode']} | {item['latexide_mac']} | **Win:** {item['latexide_windows']}<br>**Linux:** {item['latexide_linux']} | {', '.join(item['backlog_ids'])}<br>{citations} |")
    lines += ["", "## Elsődleges források és lefedettség", "", "A webes termékjellemzőket a gyártó/fejlesztő dokumentációja alapján hasonlítottuk össze. A versenytársakat ebben a futásban nem telepítettük és nem benchmarkoltuk. A forráshivatkozás termékjellemzőt igazol; az itt megadott implementáció és elfogadási feltétel saját mérnöki javaslat.", "", "| ID | Elsődleges forrás | Mire használtuk |", "| --- | --- | --- |"]
    for source in sources:
        lines.append(f"| {source['id']} | [{source['title']}]({source['url']}) | {source['scope']} |")
    (OUT / "IMPLEMENTATION_BACKLOG.md").write_text("\n".join(lines) + "\n")
    print(json.dumps(counts, ensure_ascii=False))


if __name__ == "__main__":
    generate()
